import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { withTargetVersion } from "../../../scripts/quality/with-target-version.ts";
import {
  commandTargetArgs,
  commandTargetVersions,
} from "../../../scripts/release/target-versions.ts";

const companions = [
  { angular: "16.2.12", typescript: "5.1.6", zone: "0.13.3" },
  { angular: "22.2.0", typescript: "6.0.3", zone: "0.16.0" },
  { angular: "22.2.1", typescript: "6.0.3", zone: "0.16.0" },
  { angular: "22.2.2", typescript: "6.0.3", zone: "0.16.0" },
  { angular: "22.2.5", typescript: "6.0.3", zone: "0.16.0" },
  { angular: "22.2.6", typescript: "6.0.3", zone: "0.16.0" },
];

/** Resolve the explicitly verified compiler companions for an Angular release. */
export function angularCompanion(angular: string): (typeof companions)[number] {
  const companion = companions.find((candidate) => candidate.angular === angular);
  if (!companion) throw new Error(`Missing Angular companion versions for ${angular}`);
  return companion;
}

/** Compile a standalone Angular component using the custom-element schema in its template. */
export async function checkCompatibility(
  angular: string,
  typescript: string,
  zone: string,
): Promise<void> {
  if (!/^\d+\.\d+\.\d+$/u.test(angular) || !/^\d+\.\d+\.\d+$/u.test(typescript)) {
    throw new Error(`Invalid Angular/TypeScript releases: ${angular}/${typescript}`);
  }
  await withTargetVersion(
    "@angular/compiler-cli",
    angular,
    async (_require, directory) => {
      const compilerPackage = JSON.parse(
        readFileSync(join(directory, "node_modules/@angular/compiler-cli/package.json"), "utf8"),
      ) as { bin: Record<string, string> };
      const ngc = join(directory, "node_modules/@angular/compiler-cli", compilerPackage.bin.ngc);
      writeFileSync(
        join(directory, "app.ts"),
        `import { Component, CUSTOM_ELEMENTS_SCHEMA } from "@angular/core";
@Component({ selector: "app-root", standalone: true, schemas: [CUSTOM_ELEMENTS_SCHEMA], template: '<instui-icon name="check-mark"></instui-icon>' })
export class AppComponent {}
`,
      );
      const config = join(directory, "tsconfig.json");
      writeFileSync(
        config,
        JSON.stringify({
          compilerOptions: {
            target: "ES2022",
            module: "ES2022",
            moduleResolution: "bundler",
            experimentalDecorators: true,
            strict: true,
            skipLibCheck: true,
            outDir: "out",
          },
          angularCompilerOptions: { strictTemplates: true },
          files: ["app.ts"],
        }),
      );
      const result = spawnSync(process.execPath, [ngc, "-p", config], {
        cwd: directory,
        encoding: "utf8",
      });
      if (result.error || result.status !== 0) {
        throw new Error((result.error?.message ?? result.stderr) || `ngc exited ${result.status}`);
      }
      console.log(
        `✓ Angular ${angular} / TypeScript ${typescript}: CUSTOM_ELEMENTS_SCHEMA compiled`,
      );
    },
    [
      `@angular/compiler@${angular}`,
      `@angular/core@${angular}`,
      `typescript@${typescript}`,
      "rxjs@7.8.2",
      `zone.js@${zone}`,
    ],
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const args = commandTargetArgs();
  if (args.length === 1) {
    const release = angularCompanion(args[0]);
    await checkCompatibility(release.angular, release.typescript, release.zone);
  } else if (args.length > 0) {
    if (
      args.length !== 6 ||
      args[0] !== "--version" ||
      args[2] !== "--typescript" ||
      args[4] !== "--zone"
    ) {
      throw new Error("Use --version <angular> --typescript <typescript> --zone <zone.js>");
    }
    await checkCompatibility(args[1], args[3], args[5]);
  } else {
    for (const angular of commandTargetVersions("@pantoken/angular")) {
      const release = angularCompanion(angular);
      await checkCompatibility(release.angular, release.typescript, release.zone);
    }
  }
}

